    *(const void **)&language.small_parse_table = aios_ts_table(aios_packed_ts_small_parse_table, 29598, 182024, 2);
    *(const void **)&language.small_parse_table_map = aios_ts_table(aios_packed_ts_small_parse_table_map, 3257, 10124, 4);
